import pandas as pd


def region_summary(df):
    out = {}
    for i in range(len(df)):
        r = df.iloc[i]["region"]
        out[r] = out.get(r, 0) + df.iloc[i]["w"]
    return pd.DataFrame({"region": list(out), "total_weight": list(out.values())})
